import type { AnswerRecord } from '../answerBank.js';
type AnswerName = string | readonly string[];
type TierGroup = { score: number; tier: string; note: string; names: AnswerName[] };
function records(...groups: TierGroup[]): AnswerRecord[] {
  return groups.flatMap((group) => group.names.map((name) => ({
    aliases: typeof name === 'string' ? [name] : [...name], score: group.score, tier: group.tier, note: group.note
  })));
}
function tiered(items: AnswerName[], note: string, sizes: readonly [number, number, number, number]): AnswerRecord[] {
  const [background, familiar, uncommon, rare] = sizes;
  if (items.length < background + familiar + uncommon + rare + 1) throw new Error('Not enough answers for rarity tiers');
  const groups: TierGroup[] = []; let cursor = 0;
  const add = (score: number, tier: string, count: number, familiarity: string) => {
    groups.push({ score, tier, note: familiarity + ' ' + note, names: items.slice(cursor, cursor + count) }); cursor += count;
  };
  add(10, 'BACKGROUND', background, 'A highly familiar answer.');
  add(15, 'FAMILIAR', familiar, 'A familiar answer.');
  add(30, 'UNCOMMON', uncommon, 'A less common but recognizable answer.');
  add(60, 'RARE', rare, 'A relatively obscure qualifying answer.');
  add(85, 'DEEP CUT', items.length - cursor - 1, 'A specialist-level or obscure qualifying answer.');
  add(100, 'SIGNAL FOUND', 1, 'An exceptionally obscure, independently defensible answer.');
  return records(...groups);
}
